SET NOCOUNT ON; SET XACT_ABORT ON;
IF DB_NAME() <> N'TTSmart_Operational_V1_Test' OR NOT EXISTS(SELECT 1 FROM dbo.SchemaVersions WHERE ModuleCode=N'Operational' AND MigrationNumber=1) OR NOT EXISTS(SELECT 1 FROM dbo.DatabaseInfo) THROW 58200,N'Thiếu tiền điều kiện hoặc DatabaseInfo.',1;
IF EXISTS(SELECT 1 FROM dbo.SchemaVersions WHERE ModuleCode=N'Operational' AND MigrationNumber=2 AND ScriptChecksum='$(ScriptChecksum)') RETURN;
IF EXISTS(SELECT 1 FROM dbo.SchemaVersions WHERE ModuleCode=N'Operational' AND MigrationNumber=2) THROW 58201,N'Checksum không khớp.',1;
BEGIN TRANSACTION;
DECLARE @OperationalMigrationLockResult int;
EXEC @OperationalMigrationLockResult = sys.sp_getapplock @Resource=N'TTSmart.Operational.V1.Baseline', @LockMode=N'Exclusive', @LockOwner=N'Transaction', @LockTimeout=60000;
IF @OperationalMigrationLockResult < 0 THROW 58290,N'Không lấy được application lock Operational v1.',1;
IF EXISTS(SELECT 1 FROM dbo.SchemaVersions WHERE ModuleCode=N'Operational' AND MigrationNumber=2 AND ScriptChecksum='$(ScriptChecksum)') BEGIN COMMIT; RETURN; END;
IF EXISTS(SELECT 1 FROM dbo.SchemaVersions WHERE ModuleCode=N'Operational' AND MigrationNumber=2) THROW 58201,N'Checksum không khớp.',1;
CREATE TABLE dbo.Users (UserId uniqueidentifier NOT NULL CONSTRAINT PK_Users PRIMARY KEY, PublicId char(24) COLLATE Latin1_General_100_BIN2 NOT NULL, DisplayName nvarchar(200) NOT NULL, Email nvarchar(320) NULL, NormalizedEmail nvarchar(320) NULL, Phone nvarchar(32) NULL, NormalizedPhone nvarchar(32) NULL, IsActive bit NOT NULL CONSTRAINT DF_Users_IsActive DEFAULT 1, SecurityStamp uniqueidentifier NOT NULL, Version int NOT NULL CONSTRAINT DF_Users_Version DEFAULT 0, SourceCreatedAtUtc datetime2(7) NULL, SourceUpdatedAtUtc datetime2(7) NULL, MigratedAtUtc datetime2(7) NULL, CreatedAtUtc datetime2(7) NOT NULL CONSTRAINT DF_Users_CreatedAtUtc DEFAULT SYSUTCDATETIME(), UpdatedAtUtc datetime2(7) NOT NULL CONSTRAINT DF_Users_UpdatedAtUtc DEFAULT SYSUTCDATETIME(), RowVersion rowversion NOT NULL, CONSTRAINT UQ_Users_PublicId UNIQUE(PublicId), CONSTRAINT CK_Users_PublicId CHECK(PublicId NOT LIKE '%[^0-9a-f]%' AND LEN(PublicId)=24), CONSTRAINT CK_Users_Email_Normalized CHECK((Email IS NULL AND NormalizedEmail IS NULL) OR (Email IS NOT NULL AND NormalizedEmail IS NOT NULL)), CONSTRAINT CK_Users_Phone_Normalized CHECK((Phone IS NULL AND NormalizedPhone IS NULL) OR (Phone IS NOT NULL AND NormalizedPhone IS NOT NULL)), CONSTRAINT CK_Users_Version CHECK(Version>=0));
CREATE UNIQUE INDEX UX_Users_NormalizedEmail ON dbo.Users(NormalizedEmail) WHERE NormalizedEmail IS NOT NULL;
CREATE UNIQUE INDEX UX_Users_NormalizedPhone ON dbo.Users(NormalizedPhone) WHERE NormalizedPhone IS NOT NULL;
CREATE TABLE dbo.UserPasswords (UserPasswordId uniqueidentifier NOT NULL CONSTRAINT PK_UserPasswords PRIMARY KEY, UserId uniqueidentifier NOT NULL, PasswordHash nvarchar(500) NOT NULL, Algorithm nvarchar(30) NOT NULL, AlgorithmVersion int NOT NULL, SecurityStamp uniqueidentifier NOT NULL, RehashRequired bit NOT NULL CONSTRAINT DF_UserPasswords_Rehash DEFAULT 0, ChangedAtUtc datetime2(7) NULL, CONSTRAINT FK_UserPasswords_User FOREIGN KEY(UserId) REFERENCES dbo.Users(UserId), CONSTRAINT UQ_UserPasswords_User UNIQUE(UserId), CONSTRAINT CK_UserPasswords_Algorithm CHECK(Algorithm=N'bcrypt'));
CREATE TABLE dbo.Roles (RoleId uniqueidentifier NOT NULL CONSTRAINT PK_Roles PRIMARY KEY, RoleCode nvarchar(64) NOT NULL, Name nvarchar(200) NOT NULL, IsActive bit NOT NULL CONSTRAINT DF_Roles_Active DEFAULT 1, CONSTRAINT UQ_Roles_Code UNIQUE(RoleCode));
CREATE TABLE dbo.Permissions (PermissionId uniqueidentifier NOT NULL CONSTRAINT PK_Permissions PRIMARY KEY, PermissionCode nvarchar(128) NOT NULL, Name nvarchar(200) NOT NULL, CONSTRAINT UQ_Permissions_Code UNIQUE(PermissionCode));
CREATE TABLE dbo.RolePermissions (RoleId uniqueidentifier NOT NULL, PermissionId uniqueidentifier NOT NULL, CONSTRAINT PK_RolePermissions PRIMARY KEY(RoleId,PermissionId), CONSTRAINT FK_RolePermissions_Role FOREIGN KEY(RoleId) REFERENCES dbo.Roles(RoleId), CONSTRAINT FK_RolePermissions_Permission FOREIGN KEY(PermissionId) REFERENCES dbo.Permissions(PermissionId));
CREATE TABLE dbo.UserRoles (UserId uniqueidentifier NOT NULL, RoleId uniqueidentifier NOT NULL, AssignedAtUtc datetime2(7) NOT NULL CONSTRAINT DF_UserRoles_Assigned DEFAULT SYSUTCDATETIME(), CONSTRAINT PK_UserRoles PRIMARY KEY(UserId,RoleId), CONSTRAINT FK_UserRoles_User FOREIGN KEY(UserId) REFERENCES dbo.Users(UserId), CONSTRAINT FK_UserRoles_Role FOREIGN KEY(RoleId) REFERENCES dbo.Roles(RoleId));
CREATE TABLE dbo.UserPermissions (UserId uniqueidentifier NOT NULL, PermissionId uniqueidentifier NOT NULL, GrantedAtUtc datetime2(7) NOT NULL CONSTRAINT DF_UserPermissions_Granted DEFAULT SYSUTCDATETIME(), CONSTRAINT PK_UserPermissions PRIMARY KEY(UserId,PermissionId), CONSTRAINT FK_UserPermissions_User FOREIGN KEY(UserId) REFERENCES dbo.Users(UserId), CONSTRAINT FK_UserPermissions_Permission FOREIGN KEY(PermissionId) REFERENCES dbo.Permissions(PermissionId));
CREATE TABLE dbo.PasswordResetRequests (PasswordResetRequestId uniqueidentifier NOT NULL CONSTRAINT PK_PasswordResetRequests PRIMARY KEY, UserId uniqueidentifier NOT NULL, TokenHash char(64) NOT NULL, ExpiresAtUtc datetime2(7) NOT NULL, UsedAtUtc datetime2(7) NULL, RevokedAtUtc datetime2(7) NULL, CreatedAtUtc datetime2(7) NOT NULL CONSTRAINT DF_PasswordResetRequests_Created DEFAULT SYSUTCDATETIME(), CONSTRAINT FK_PasswordResetRequests_User FOREIGN KEY(UserId) REFERENCES dbo.Users(UserId), CONSTRAINT UQ_PasswordResetRequests_Hash UNIQUE(TokenHash), CONSTRAINT CK_PasswordResetRequests_Hash CHECK(TokenHash NOT LIKE '%[^0-9A-F]%'));
CREATE TABLE dbo.AutoLoginTokens (AutoLoginTokenId uniqueidentifier NOT NULL CONSTRAINT PK_AutoLoginTokens PRIMARY KEY, UserId uniqueidentifier NOT NULL, TokenHash char(64) NOT NULL, SecurityStamp uniqueidentifier NOT NULL, ExpiresAtUtc datetime2(7) NOT NULL, RevokedAtUtc datetime2(7) NULL, CreatedAtUtc datetime2(7) NOT NULL CONSTRAINT DF_AutoLoginTokens_Created DEFAULT SYSUTCDATETIME(), CONSTRAINT FK_AutoLoginTokens_User FOREIGN KEY(UserId) REFERENCES dbo.Users(UserId), CONSTRAINT UQ_AutoLoginTokens_Hash UNIQUE(TokenHash), CONSTRAINT CK_AutoLoginTokens_Hash CHECK(TokenHash NOT LIKE '%[^0-9A-F]%'));
INSERT dbo.SchemaVersions SELECT NEWID(),N'Operational',2,N'002_CreateLocalIdentityTables.sql','$(ScriptChecksum)',SYSUTCDATETIME(),ORIGINAL_LOGIN(); COMMIT;
GO
